// ============================================================
// Generic helpers
// ============================================================

// copyRows iterates a SELECT, then INSERTs each row into target with the
// same column count. nCols must match the INSERT placeholder count.
func copyRows(rows *sql.Rows, queryErr error, t *sql.DB, insertSQL string, nCols int) (int, error) {
	if queryErr != nil {
		return 0, fmt.Errorf("select: %w", queryErr)
	}
	defer rows.Close()

	count := 0
	for rows.Next() {
		vals := make([]interface{}, nCols)
		valPtrs := make([]interface{}, nCols)
		for i := range vals {
			valPtrs[i] = &vals[i]
		}
		if err := rows.Scan(valPtrs...); err != nil {
			log.Printf("scan: %v", err)
			continue
		}
		if _, err := t.Exec(insertSQL, vals...); err != nil {
			log.Printf("insert (id=%v): %v", vals[0], err)
			continue
		}
		count++
	}
	return count, nil
}

// migJSONBToObjectPerms reads a SELECT where one column is a JSONB array
// of action names, splits it into seven boolean cols, and inserts.
// `keyCols` is the comma-separated PG col list for the BEFORE-jsonb cols.
func migJSONBToObjectPerms(pg, t *sql.DB, selectSQL, insertSQL, keyCols string) (int, error) {
	rows, err := pg.Query(selectSQL)
	if err != nil {
		return 0, fmt.Errorf("select: %w", err)
	}
	defer rows.Close()

	cols, err := rows.Columns()
	if err != nil {
		return 0, fmt.Errorf("columns: %w", err)
	}
	jsonbIdx := indexOf(cols, "permission")
	if jsonbIdx < 0 {
		return 0, fmt.Errorf("no permission col")
	}

	count := 0
	for rows.Next() {
		raw := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range raw {
			ptrs[i] = &raw[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			log.Printf("scan: %v", err)
			continue
		}

		perms := decodeJSONBArray(raw[jsonbIdx])
		cv, cc, ce, cd, ca, cex, cp := core.PermissionActionsToFlags(perms)

		// Build target args: BEFORE-jsonb cols, then 7 flags, then AFTER-jsonb cols
		out := make([]interface{}, 0, len(cols)+6)
		out = append(out, raw[:jsonbIdx]...)
		out = append(out, cv, cc, ce, cd, ca, cex, cp)
		out = append(out, raw[jsonbIdx+1:]...)

		if _, err := t.Exec(insertSQL, out...); err != nil {
			log.Printf("insert (key=%v): %v", raw[0], err)
			continue
		}
		count++
	}
	return count, nil
}

func migJSONBToDataAccessPerms(pg, t *sql.DB, selectSQL, insertSQL, keyCols string) (int, error) {
	rows, err := pg.Query(selectSQL)
	if err != nil {
		return 0, fmt.Errorf("select: %w", err)
	}
	defer rows.Close()

	cols, err := rows.Columns()
	if err != nil {
		return 0, fmt.Errorf("columns: %w", err)
	}
	jsonbIdx := indexOf(cols, "permission")
	if jsonbIdx < 0 {
		jsonbIdx = indexOf(cols, "permissions")
	}
	if jsonbIdx < 0 {
		return 0, fmt.Errorf("no permission(s) col")
	}

	count := 0
	for rows.Next() {
		raw := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range raw {
			ptrs[i] = &raw[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			log.Printf("scan: %v", err)
			continue
		}

		perms := decodeJSONBArray(raw[jsonbIdx])
		cv, cex, csh, cp := core.DataAccessActionsToFlags(perms)

		out := make([]interface{}, 0, len(cols)+3)
		out = append(out, raw[:jsonbIdx]...)
		out = append(out, cv, cex, csh, cp)
		out = append(out, raw[jsonbIdx+1:]...)

		if _, err := t.Exec(insertSQL, out...); err != nil {
			log.Printf("insert (key=%v): %v", raw[0], err)
			continue
		}
		count++
	}
	return count, nil
}

// migLtreeToAgencyID reads a row containing agency_path text, splits the
// dotted path, takes the LAST segment as AGC_CODE, and looks up AGC_ID.
// agcCol is the 0-based index of agency_path in the SELECT result.
func migLtreeToAgencyID(pg, t *sql.DB, selectSQL, insertSQL string, agcColIdx int) (int, error) {
	rows, err := pg.Query(selectSQL)
	if err != nil {
		return 0, fmt.Errorf("select: %w", err)
	}
	defer rows.Close()

	// cache AGC_CODE → AGC_ID (UUID string)
	cache := map[string]string{}

	count := 0
	skipped := 0
	for rows.Next() {
		cols, _ := rows.Columns()
		raw := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range raw {
			ptrs[i] = &raw[i]
		}
		if err := rows.Scan(ptrs...); err != nil {
			log.Printf("scan: %v", err)
			continue
		}

		path, _ := raw[agcColIdx].(string)
		segments := strings.Split(path, ".")
		lastCode := strings.TrimSpace(segments[len(segments)-1])

		var agcID string
		if v, ok := cache[lastCode]; ok {
			agcID = v
		} else {
			err := t.QueryRow(`SELECT AGC_ID FROM APP.M_AGC WHERE AGC_CODE = :1 FETCH FIRST 1 ROWS ONLY`, lastCode).Scan(&agcID)
			if err != nil {
				log.Printf("agency_path %q (code %q) not found in M_AGC — skipping (key=%v)", path, lastCode, raw[0])
				skipped++
				continue
			}
			cache[lastCode] = agcID
		}

		// Replace agency_path with agency_id (UUID string)
		raw[agcColIdx] = agcID

		if _, err := t.Exec(insertSQL, raw...); err != nil {
			log.Printf("insert (key=%v): %v", raw[0], err)
			continue
		}
		count++
	}
	if skipped > 0 {
		log.Printf("  (%d rows skipped due to missing agency mapping)", skipped)
	}
	return count, nil
}

// decodeJSONBArray accepts what database/sql gives for a PG JSONB column
// — typically []byte or string — and returns the action names array.
func decodeJSONBArray(v interface{}) []string {
	if v == nil {
		return nil
	}
	var raw []byte
	switch x := v.(type) {
	case []byte:
		raw = x
	case string:
		raw = []byte(x)
	default:
		return nil
	}
	if len(raw) == 0 {
		return nil
	}
	var out []string
	if err := json.Unmarshal(raw, &out); err == nil {
		return out
	}
	return nil
}

func indexOf(ss []string, target string) int {
	for i, s := range ss {
		if s == target {
			return i
		}
	}
	return -1
}

// ============================================================
// FK + identity helpers
// ============================================================

func disableTargetFKs(t *sql.DB) {
	rows, err := t.Query(`
		SELECT table_name, constraint_name FROM user_constraints
		 WHERE constraint_type = 'R' AND status = 'ENABLED'`)
	if err != nil {
		log.Printf("list FKs: %v", err)
		return
	}
	defer rows.Close()

	for rows.Next() {
		var tab, con string
		if err := rows.Scan(&tab, &con); err != nil {
			continue
		}
		if _, err := t.Exec(`ALTER TABLE ` + tab + ` DISABLE CONSTRAINT ` + con); err != nil {
			log.Printf("disable %s.%s: %v", tab, con, err)
		}
	}
}

func enableTargetFKs(t *sql.DB) {
	rows, err := t.Query(`
		SELECT table_name, constraint_name FROM user_constraints
		 WHERE constraint_type = 'R' AND status = 'DISABLED'`)
	if err != nil {
		log.Printf("list FKs: %v", err)
		return
	}
	defer rows.Close()

	for rows.Next() {
		var tab, con string
		if err := rows.Scan(&tab, &con); err != nil {
			continue
		}
		if _, err := t.Exec(`ALTER TABLE ` + tab + ` ENABLE CONSTRAINT ` + con); err != nil {
			log.Printf("enable %s.%s: %v", tab, con, err)
		}
	}
}

// resyncIdentitySequences sets each IDENTITY column's next value to
// MAX(id)+1 so future inserts don't collide with imported rows.
func resyncIdentitySequences(t *sql.DB) {
	type idTab struct {
		table string
		idCol string
	}
	tables := []idTab{
		{"permission_type", "id"}, {"object_type", "id"},
		{"domain", "id"}, {"application", "id"}, {"module", "id"}, {"object", "id"},
		{"process", "id"}, {"sub_process", "id"}, {"process_mapper", "id"},
		{"user_info", "user_id"},
		{"role", "id"}, {"role_object_mapping", "id"}, {"role_object_permission", "id"},
		{"responsibility", "id"}, {"responsibility_role_mapping", "id"},
		{"responsibility_role_permission", "id"},
		{"responsibility_data_access", "id"}, {"responsibility_data_access_permission", "id"},
		{"user_role_mapping", "id"}, {"user_responsibility_mapping", "id"},
		{"user_custom_object_mapping", "id"}, {"user_custom_object_permission", "id"},
		{"user_custom_data_access", "id"}, {"user_custom_data_access_permission", "id"},
		{"menu_access_logs", "menu_access_logs_id"},
	}
	for _, tab := range tables {
		// Re-anchor the identity to max+1 using START WITH LIMIT VALUE: Oracle reads
		// MAX(id) itself as part of the DDL. Computing max+1 here and passing it as a
		// partially loaded table, so the ALTER moved the sequence BACKWARD onto ids
		// that already existed and every later insert died with ORA-00001 on the PK.
		_, err := t.Exec(fmt.Sprintf(
			`ALTER TABLE %s MODIFY (%s GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE))`,
			tab.table, tab.idCol))
		if err != nil {
			log.Printf("resync %s.%s: %v", tab.table, tab.idCol, err)
		}
	}
	log.Println("✓ identity sequences re-anchored")
}

func mustExec(t *sql.DB, sqlStmt string) {
	if _, err := t.Exec(sqlStmt); err != nil {
		log.Printf("exec failed (continuing): %s\n  %v", strings.TrimSpace(sqlStmt), err)
	}
}
